/bin/bash -lc "python - <<'PY'
from collections import Counter
for f in ['human.paf','mouse.paf','pig.paf']:
 c=Counter(); mult=Counter(); qrecs=Counter();
 for l in open(f):
  a=l.rstrip().split('\\t'); q=a[0]; qrecs[q]+=1
  tags={x.split(':',2)[0]:x.split(':',2)[2] for x in a[12:]}
  c[(tags.get('tp'),a[11])]+=1
 print(f,'records',sum(c.values()),'tp/mapq',c.most_common(10),'multi q',sum(v>1 for v in qrecs.values()),'max',max(qrecs.values()))
PY"
